select jsonb_build_object('provider_observations',(select count(*) from provider_observations),'contest_results',(select count(*) from contest_results),'ingestion_quarantine',(select count(*) from ingestion_quarantine),'provider_entity_refs',(select count(*) from provider_entity_refs),'event_provider_attempts',(select count(*) from event_provider_attempts),'notification_attempts',(select count(*) from notification_attempts),'provider_rate_budget_reservations',(select count(*) from provider_rate_budget_reservations),'ingestion_runs',(select count(*) from ingestion_runs),
'control',(select jsonb_build_object('stopped',global_stopped,'notifications',notifications_enabled,'realSends',real_sends_enabled) from event_runtime_control),
'results',(select jsonb_agg(jsonb_build_object('outcome',outcome_type,'version',version,'winner',winner_event_entry_id,'attributed',source_observation_id is not null)) from contest_results),
'leaderboard',(select jsonb_agg(jsonb_build_object('leagueId',league_id,'state',lifecycle_state,'leaderboard',leaderboard) order by league_id) from event_league_evaluations),
'runs',(select jsonb_agg(jsonb_build_object('status',status,'errorClass',error_class,'metadata',metadata) order by created_at) from ingestion_runs),
'budget',(select jsonb_build_object('limit',configured_limit_count,'remaining',available_count) from provider_rate_budgets));
